package com.pavithran.aichat.model; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="messages") public class Message { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID conversationId; @Column(nullable=false) String role; @Column(nullable=false,columnDefinition="TEXT") String content; @Column(nullable=false) Instant createdAt=Instant.now(); public UUID getId(){return id;} public UUID getConversationId(){return conversationId;} public void setConversationId(UUID v){conversationId=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public Instant getCreatedAt(){return createdAt;} }
